-- PRIVATE-only boundary fixture: no actual keys/audience/transport provisioned. Every change rolls back.
DO $$ DECLARE run text:=replace(gen_random_uuid()::text,'-','');cid text:='svc-test-'||run;kid text:='svc-key-'||run;
 inst text:='vi-service-'||run;ep text:='ep-service-'||run;env jsonb;q jsonb;r jsonb;raw text;hash text;passed int:=0;n int;f text;bad jsonb;actor uuid:=gen_random_uuid();
BEGIN
 INSERT INTO gw_tenant_members(user_id,tenant_id,role) VALUES(actor,'grp-syn-northwind','admin');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 IF has_function_privilege('authenticated','public.gw_service_execute(text,text,text,timestamptz,text,text,inet)','EXECUTE') OR has_function_privilege('anon','public.gw_service_execute(text,text,text,timestamptz,text,text,inet)','EXECUTE') OR has_table_privilege('authenticated','public.gw_service_keys','SELECT') OR has_table_privilege('authenticated','public.gw_service_connections','INSERT') THEN RAISE EXCEPTION 'BROWSER_SERVICE_ACCESS';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-nonce-default-001',clock_timestamp(),'{}',repeat('0',64),'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 503 THEN RAISE EXCEPTION 'DEFAULT_GATE_OPEN';END IF;passed:=passed+1;
 INSERT INTO gw_service_stage_gates(id,enabled,audience_reviewed,threat_reviewed,private_transport,evidence_ref) VALUES(1,true,true,true,true,'rollback-unit-only') ON CONFLICT(id) DO UPDATE SET enabled=true,audience_reviewed=true,threat_reviewed=true,private_transport=true;
 INSERT INTO gw_service_connections(connection_id,app,tenant_id,rooftop_ids,endpoint_ref,network_allowlist,provisioned_by,enabled) VALUES(cid,'autocurb','grp-syn-northwind',ARRAY['rt-syn-nw-01'],'local-test:'||cid,ARRAY['127.0.0.1'::inet],gen_random_uuid(),true);
 INSERT INTO gw_service_keys(key_id,connection_id,fingerprint,key_role,directions,event_types,targets,not_before,not_after,rotate_after,budget_per_min) VALUES(kid,cid,repeat('a',64),'event_publisher',ARRAY['event_push'],ARRAY['appraisal.completed'],ARRAY['autolabels','autofilm']::gw_app[],clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 hour',clock_timestamp()+interval '30 minutes',120);
 env:=jsonb_build_object('event_id',gen_random_uuid(),'schema_version',1,'tenant_id','grp-syn-northwind','rooftop_id','rt-syn-nw-01','source_app','autocurb','event_type','appraisal.completed','aggregate',jsonb_build_object('type','vehicle_instance','id',inst,'revision',1),'vehicle',jsonb_build_object('vin','DEVSYNSV'||upper(substr(run,1,9)),'instance_id',inst,'episode_id',ep),'occurred_at',clock_timestamp(),'emitted_at',clock_timestamp(),'payload',jsonb_build_object('acv_value',101,'acv_cents',102,'offered_price',103,'finance_amount',104,'nested',jsonb_build_object('acv_value',105)));
 q:=jsonb_build_object('protocol','gw.service-staging/1','app','autocurb','direction','event_push','tenant','grp-syn-northwind','rooftop','rt-syn-nw-01','body',env);raw:=q::text;hash:=encode(extensions.digest(raw,'sha256'),'hex');
 r:=gw_service_execute(kid,repeat('a',64),'service-nonce-accepted-001',clock_timestamp(),raw,hash,'127.0.0.1');IF r->>'decision' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'SERVICE_ACCEPT_FAILED: %',r->>'reason';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-nonce-accepted-001',clock_timestamp(),raw,hash,'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 409 THEN RAISE EXCEPTION 'SERVICE_NONCE_REPLAY';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-nonce-duplicate-001',clock_timestamp(),raw,hash,'127.0.0.1');IF r->>'decision' IS DISTINCT FROM 'duplicate' THEN RAISE EXCEPTION 'SERVICE_IDEMPOTENCY';END IF;passed:=passed+1;
 SELECT count(*) INTO n FROM gw_service_receipts WHERE key_id=kid AND decision='accepted';IF n<>1 THEN RAISE EXCEPTION 'MULTIPLE_ACCEPT_RECEIPTS';END IF;passed:=passed+1;
 FOREACH f IN ARRAY ARRAY['app','tenant','rooftop','direction'] LOOP bad:=q||jsonb_build_object(f,CASE f WHEN 'app' THEN 'autofilm' WHEN 'tenant' THEN 'grp-prod-test' WHEN 'rooftop' THEN 'rt-syn-nw-02' ELSE 'authorized_pull' END);raw:=bad::text;r:=gw_service_execute(kid,repeat('a',64),'service-negative-'||f||run,clock_timestamp(),raw,encode(extensions.digest(raw,'sha256'),'hex'),'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 403 THEN RAISE EXCEPTION 'SERVICE_SCOPE_FAILURE';END IF;passed:=passed+1;END LOOP;
 raw:=q::text;
 r:=gw_service_execute(kid,repeat('b',64),'service-bad-fingerprint-01',clock_timestamp(),raw,hash,'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 401 THEN RAISE EXCEPTION 'FINGERPRINT';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-bad-network-001',clock_timestamp(),raw,hash,'192.0.2.1');IF (r->>'http_status')::int IS DISTINCT FROM 403 THEN RAISE EXCEPTION 'NETWORK';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-bad-hash-00001',clock_timestamp(),raw,repeat('0',64),'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 400 THEN RAISE EXCEPTION 'BODY_HASH';END IF;passed:=passed+1;
 r:=gw_service_execute(kid,repeat('a',64),'service-bad-timestamp-01',clock_timestamp()-interval '301 seconds',raw,hash,'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 401 THEN RAISE EXCEPTION 'TIMESTAMP';END IF;passed:=passed+1;
 UPDATE gw_service_keys SET revoked_at=clock_timestamp() WHERE key_id=kid;r:=gw_service_execute(kid,repeat('a',64),'service-revoked-00001',clock_timestamp(),raw,hash,'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 401 THEN RAISE EXCEPTION 'REVOCATION';END IF;passed:=passed+1;UPDATE gw_service_keys SET revoked_at=NULL WHERE key_id=kid;
 UPDATE gw_settings SET global_kill=true WHERE id=1;r:=gw_service_execute(kid,repeat('a',64),'service-kill-00000001',clock_timestamp(),raw,hash,'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 503 THEN RAISE EXCEPTION 'GLOBAL_KILL';END IF;passed:=passed+1;UPDATE gw_settings SET global_kill=false WHERE id=1;
 -- Apply only fresh fixture rows via internal claim, without touching shared projections or lanes.
 FOR n IN 1..3 LOOP PERFORM gw_worker_step('service-privacy',100,50);END LOOP;
 SELECT state->'appraisal' INTO r FROM gw_projections WHERE tenant_id='grp-syn-northwind' AND aggregate_id=inst AND target_app='autofilm';
 FOREACH f IN ARRAY ARRAY['acv_value','acv_cents','offered_price','finance_amount'] LOOP IF r IS NULL OR r::text LIKE '%'||f||'%' THEN RAISE EXCEPTION 'SERVICE_ACV_PROJECTION';END IF;passed:=passed+1;END LOOP;
 RAISE EXCEPTION 'GW_TESTS_PASSED: %',passed;
END $$;